    /**
     * Method to retrieve the Routing via RoutingFetchOneSummary
     * @param 	summary RoutingFetchOneSummary 
     * @return 	RoutingFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Routing getRouting( RoutingFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "RoutingFetchOneSummary arg cannot be null" );
    	
    	Routing entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Routing
        	// --------------------------------------
        	CompletableFuture<Routing> futureEntity = queryGateway.query(new FindRoutingQuery( new LoadRoutingFilter( summary.getRoutingId() ) ), ResponseTypes.instanceOf(Routing.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Routing with id " + summary.getRoutingId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


